static TalkValue talk_static_string(uint32_t id) {
    if (id >= talk_static_string_count) talk_trap("static string index out of range");
    if (talk_static_string_cache[id].tag != TALK_NATIVE) {
        const TalkStaticStringDesc *desc = &talk_static_string_descs[id];
        talk_static_string_cache[id] = talk_static_string_value(
            desc->layout, desc->display, talk_statics + desc->offset, (int64_t)desc->len);
    }
    return talk_static_string_cache[id];
}
static TalkValue talk_static_string_tagged(uint32_t id) {
    if (id >= talk_static_string_count) talk_trap("static string index out of range");
    if (talk_static_string_tagged_cache[id].tag != TALK_AGG) {
        const TalkStaticStringDesc *desc = &talk_static_string_descs[id];
        TalkValue value = talk_static_agg(desc->layout, desc->display, 0, 3);
        value.v.agg->fields[0] = talk_pointer(talk_statics + desc->offset);
        value.v.agg->fields[1] = talk_int((int64_t)desc->len);
        value.v.agg->fields[2] = talk_int((int64_t)desc->len);
        talk_static_string_tagged_cache[id] = value;
    }
    return talk_static_string_tagged_cache[id];
}
