/* ---- library boundary (ADR 0048), ABI version 1 ---- */
#include <stddef.h>
_Static_assert(sizeof(TalkValue) == 16, "the library value ABI assumes 16-byte values");
_Static_assert(offsetof(TalkValue, v) == 8, "the library value ABI assumes the payload at offset 8");
#define TALK_LIB_OK 0
#define TALK_LIB_ERR_ARITY 1
#define TALK_LIB_ERR_TRAP 2
#define TALK_LIB_ERR_EXIT 3
#define TALK_LIB_ERR_STATE 4
#define TALK_LIB_ERR_VALUE 5

static void talk_lib_cleanup(void) {
    talk_lib_reset();
    memset(talk_globals, 0, sizeof talk_globals);
    talk_lib_initialized = 0;
}

int talk_frontend_init(void) {
    if (talk_lib_initialized) {
        return TALK_LIB_ERR_STATE;
    }
    talk_argc = 0;
    talk_argv = NULL;
    talk_statics_base = talk_statics;
    talk_statics_len = sizeof talk_statics;
    talk_types = talk_type_table;
    talk_type_count = sizeof talk_type_table / sizeof *talk_type_table;
    talk_layouts = talk_layout_table;
    talk_layout_count = sizeof talk_layout_table / sizeof *talk_layout_table;
    talk_lib_message[0] = '\0';
    talk_lib_exit_status = 0;
    talk_lib_initialized = 1;
    return TALK_LIB_OK;
}

void talk_frontend_teardown(void) {
    if (talk_lib_initialized) {
        talk_lib_cleanup();
    }
}

const char *talk_frontend_error_message(void) {
    return talk_lib_message;
}

int talk_frontend_exit_status(void) {
    return talk_lib_exit_status;
}

static int talk_lib_value_error(const char *what) {
    snprintf(talk_lib_message, sizeof talk_lib_message, "%s", what);
    return TALK_LIB_ERR_VALUE;
}

static TalkValue talk_lib_plain(TalkValue value) {
    return value.tag == TALK_NATIVE ? talk_native_retag(value) : value;
}

/* The aggregate view: display identity, live variant tag (-1 for
   products), and logical member count. */
int talk_frontend_value_view(TalkValue value, uint32_t *display, int32_t *tag, uint32_t *len) {
    value = talk_lib_plain(value);
    if (value.tag != TALK_AGG) {
        return talk_lib_value_error("a non-aggregate value has no view");
    }
    TalkAgg *agg = value.v.agg;
    *display = agg->symbol;
    if (agg->layout == TALK_DYN || agg->layout >= talk_layout_count) {
        *tag = -1;
        *len = agg->len;
        return TALK_LIB_OK;
    }
    const TalkLayoutInfo *info = &talk_layouts[agg->layout];
    if (info->is_sum) {
        uint32_t live = (uint32_t)agg->fields[0].v.i;
        if (live >= info->variant_count) {
            return talk_lib_value_error("enum tag out of range");
        }
        *tag = (int32_t)live;
        *len = info->variant_starts[live + 1] - info->variant_starts[live];
    } else {
        *tag = -1;
        *len = info->field_count;
    }
    return TALK_LIB_OK;
}

/* One logical member: a product's declared field or the live
   variant's payload. Spliced children reconstruct in the arena, so
   an out-of-memory trap is contained here like a wrapper call. */
int talk_frontend_value_element(TalkValue value, uint32_t index, TalkValue *out) {
    value = talk_lib_plain(value);
    if (value.tag != TALK_AGG) {
        return talk_lib_value_error("a non-aggregate value has no members");
    }
    TalkAgg *agg = value.v.agg;
    switch (setjmp(talk_lib_boundary)) {
    case 0:
        break;
    default:
        talk_lib_cleanup();
        return TALK_LIB_ERR_TRAP;
    }
    talk_lib_boundary_armed = 1;
    int status = TALK_LIB_OK;
    if (agg->layout == TALK_DYN || agg->layout >= talk_layout_count) {
        if (index >= agg->len) {
            status = talk_lib_value_error("member index out of range");
        } else {
            *out = agg->fields[index];
        }
    } else {
        const TalkLayoutInfo *info = &talk_layouts[agg->layout];
        if (info->is_sum) {
            uint32_t live = (uint32_t)agg->fields[0].v.i;
            if (live >= info->variant_count
                || index >= info->variant_starts[live + 1] - info->variant_starts[live]) {
                status = talk_lib_value_error("payload index out of range");
            } else {
                *out = talk_field_at(value, &info->fields[info->variant_starts[live] + index]);
            }
        } else if (index >= info->field_count) {
            status = talk_lib_value_error("member index out of range");
        } else {
            *out = talk_field_at(value, &info->fields[index]);
        }
    }
    talk_lib_boundary_armed = 0;
    return status;
}

/* A string's bytes: borrowed until teardown or a failed call. */
int talk_frontend_string_read(TalkValue value, const unsigned char **bytes, uint64_t *len) {
    value = talk_lib_plain(value);
    if (value.tag != TALK_AGG || value.v.agg->len < 2
        || value.v.agg->fields[0].tag != TALK_PTR
        || value.v.agg->fields[1].tag != TALK_INT) {
        return talk_lib_value_error("value is not a string");
    }
    *bytes = value.v.agg->fields[0].v.ptr;
    *len = (uint64_t)value.v.agg->fields[1].v.i;
    return TALK_LIB_OK;
}

/* Raw array storage reads: an 8-byte word or one byte at an index
   off a storage base pointer. */
int talk_frontend_array_word(TalkValue base, uint64_t index, uint64_t *out) {
    if (base.tag != TALK_PTR) {
        return talk_lib_value_error("array storage is not a pointer");
    }
    memcpy(out, base.v.ptr + index * 8, 8);
    return TALK_LIB_OK;
}

int talk_frontend_array_byte(TalkValue base, uint64_t index, uint8_t *out) {
    if (base.tag != TALK_PTR) {
        return talk_lib_value_error("array storage is not a pointer");
    }
    *out = base.v.ptr[index];
    return TALK_LIB_OK;
}

/* A boxed array element: the stored word is a cell pointer. */
int talk_frontend_boxed_read(uint64_t word, TalkValue *out) {
    TalkValue *cell = (TalkValue *)(uintptr_t)word;
    if (cell == NULL) {
        return talk_lib_value_error("null boxed array element");
    }
    *out = *cell;
    return TALK_LIB_OK;
}

/* The display-id-to-module-symbol table, for record identity
   validation against an ABI descriptor. */
uint32_t talk_frontend_symbol_count(void) {
    return (uint32_t)(sizeof talk_lib_symbols / sizeof *talk_lib_symbols);
}

int talk_frontend_symbol(uint32_t display, uint8_t *kind, uint32_t *module, uint32_t *local) {
    if (display >= sizeof talk_lib_symbols / sizeof *talk_lib_symbols) {
        return talk_lib_value_error("display id out of range");
    }
    *kind = talk_lib_symbols[display].kind;
    *module = talk_lib_symbols[display].module;
    *local = talk_lib_symbols[display].local;
    return TALK_LIB_OK;
}

/* Construct a Talk String over host bytes, allocated inside the
   library so teardown reclaims it. */
int talk_frontend_string_new(TalkValue *out, const unsigned char *bytes, uint64_t len) {
    if (!talk_lib_initialized) {
        return TALK_LIB_ERR_STATE;
    }
    switch (setjmp(talk_lib_boundary)) {
    case 0:
        break;
    default:
        talk_lib_cleanup();
        return TALK_LIB_ERR_TRAP;
    }
    talk_lib_boundary_armed = 1;
    TalkValue storage = talk_alloc(talk_int((int64_t)len));
    if (len != 0) {
        memcpy(storage.v.ptr, bytes, (size_t)len);
    }
    TalkValue built = talk_agg(1u, 1u, 0, 3);
    built.v.agg->fields[0] = storage;
    built.v.agg->fields[1] = talk_int((int64_t)len);
    built.v.agg->fields[2] = talk_int((int64_t)len);
    talk_lib_boundary_armed = 0;
    *out = built;
    return TALK_LIB_OK;
}

/* export "lex" */
int talk_frontend_lex(TalkValue *out, const TalkValue *args, size_t argc) {
    if (!talk_lib_initialized) {
        return TALK_LIB_ERR_STATE;
    }
    if (argc != 1) {
        snprintf(talk_lib_message, sizeof talk_lib_message,
                 "export \"lex\" takes 1 argument(s), got %zu", argc);
        return TALK_LIB_ERR_ARITY;
    }
    { char anchor; talk_stack_init((uintptr_t)&anchor); }
    switch (setjmp(talk_lib_boundary)) {
    case 0:
        break;
    case 2:
        talk_lib_cleanup();
        return TALK_LIB_ERR_EXIT;
    default:
        talk_lib_cleanup();
        return TALK_LIB_ERR_TRAP;
    }
    talk_lib_boundary_armed = 1;
    TalkValue result = talk_fn2(NULL, args[0]);
    talk_lib_boundary_armed = 0;
    if (out != NULL) {
        *out = result;
    }
    return TALK_LIB_OK;
}

